// Wire enums. The spec locks the declared value sets at 1.0, and a response
// may still carry a value a newer server added: it decodes as its wire string
// and Valid() reports false, while a request must carry a declared value. The
// generated types and their constants are re-exported here so callers write
// ezclassify.AssertionConfidenceCertain instead of a raw string, and get the
// Valid() membership check without importing internal/api.
type (
	ConceptNoticeType      = api.ConceptNoticeType
	ProcessingRole         = api.ProcessingRole
	WarningKind            = api.WarningKind
	DocumentOverallVerdict = api.DocumentOverallVerdict
	FixAction              = api.FixAction
)

